import java.io.*;
import java.util.*;

public class Main {
    public static class Task {
        // Use separate classes but with different naming and structure
        static class Dinic {
            static class Edge {
                int t, rev;
                long cap, f;
                Edge(int t, int rev, long cap) { this.t = t; this.rev = rev; this.cap = cap; }
            }
            List<Edge>[] g;
            Dinic(int n) {
                g = new List[n];
                for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
            }
            void add(int s, int t, long cap) {
                g[s].add(new Edge(t, g[t].size(), cap));
                g[t].add(new Edge(s, g[s].size() - 1, 0));
            }
            boolean bfs(int s, int t, int[] d) {
                Arrays.fill(d, -1);
                d[s] = 0;
                int[] q = new int[g.length];
                int qs = 0;
                q[qs++] = s;
                for (int i = 0; i < qs; i++) {
                    int u = q[i];
                    for (Edge e : g[u]) {
                        if (d[e.t] < 0 && e.f < e.cap) {
                            d[e.t] = d[u] + 1;
                            q[qs++] = e.t;
                        }
                    }
                }
                return d[t] >= 0;
            }
            long dfs(int[] ptr, int[] d, int t, int u, long f) {
                if (u == t) return f;
                for (; ptr[u] < g[u].size(); ++ptr[u]) {
                    Edge e = g[u].get(ptr[u]);
                    if (d[e.t] == d[u] + 1 && e.f < e.cap) {
                        long df = dfs(ptr, d, t, e.t, Math.min(f, e.cap - e.f));
                        if (df > 0) {
                            e.f += df;
                            g[e.t].get(e.rev).f -= df;
                            return df;
                        }
                    }
                }
                return 0;
            }
            long maxFlow(int s, int t) {
                long flow = 0;
                int[] d = new int[g.length];
                while (bfs(s, t, d)) {
                    int[] ptr = new int[g.length];
                    while (true) {
                        long df = dfs(ptr, d, t, s, Long.MAX_VALUE);
                        if (df == 0) break;
                        flow += df;
                    }
                }
                return flow;
            }
        }

        static class MinCost {
            static class Edge {
                int to, f, cap, cost, rev;
                Edge(int to, int cap, int cost, int rev) {
                    this.to = to; this.cap = cap; this.cost = cost; this.rev = rev;
                }
            }
            List<Edge>[] g;
            MinCost(int n) {
                g = new List[n];
                for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
            }
            void add(int s, int t, int cap, int cost) {
                g[s].add(new Edge(t, cap, cost, g[t].size()));
                g[t].add(new Edge(s, 0, -cost, g[s].size() - 1));
            }
            void spfa(int s, int[] dist, int[] prevNode, int[] prevEdge, int[] curFlow) {
                int n = g.length;
                Arrays.fill(dist, 0, n, Integer.MAX_VALUE);
                dist[s] = 0;
                curFlow[s] = Integer.MAX_VALUE;
                boolean[] inQ = new boolean[n];
                Queue<Integer> q = new LinkedList<>();
                q.add(s);
                inQ[s] = true;
                while (!q.isEmpty()) {
                    int u = q.poll();
                    inQ[u] = false;
                    for (int i = 0; i < g[u].size(); i++) {
                        Edge e = g[u].get(i);
                        if (e.f >= e.cap) continue;
                        int v = e.to;
                        int nd = dist[u] + e.cost;
                        if (dist[v] > nd) {
                            dist[v] = nd;
                            prevNode[v] = u;
                            prevEdge[v] = i;
                            curFlow[v] = Math.min(curFlow[u], e.cap - e.f);
                            if (!inQ[v]) {
                                inQ[v] = true;
                                q.add(v);
                            }
                        }
                    }
                }
            }
            int[] minCostFlow(int s, int t, int maxf) {
                int n = g.length;
                int[] dist = new int[n];
                int[] curFlow = new int[n];
                int[] prevEdge = new int[n];
                int[] prevNode = new int[n];
                int flow = 0, cost = 0;
                while (flow < maxf) {
                    spfa(s, dist, prevNode, prevEdge, curFlow);
                    if (dist[t] == Integer.MAX_VALUE) break;
                    int df = Math.min(curFlow[t], maxf - flow);
                    flow += df;
                    for (int v = t; v != s; v = prevNode[v]) {
                        Edge e = g[prevNode[v]].get(prevEdge[v]);
                        e.f += df;
                        g[v].get(e.rev).f -= df;
                        cost += df * e.cost;
                    }
                }
                return new int[]{flow, cost};
            }
        }

        public void solve(Scanner sc, PrintWriter pw) throws IOException {
            int N = sc.nextInt();
            int M = sc.nextInt();
            int K = sc.nextInt();
            int C = sc.nextInt();
            int D = sc.nextInt();
            int[] pos = new int[N];
            for (int i = 0; i < K; i++) pos[sc.nextInt() - 1]++;
            int T = 100;
            MinCost mf = new MinCost((T + 1) * N + 2);
            for (int i = 0; i < N; i++) if (pos[i] > 0) mf.add(0, i + 1, pos[i], 0);
            for (int i = 0; i < T; i++) for (int j = 0; j < N; j++) mf.add(1 + i * N + j, 1 + (i + 1) * N + j, K, 0);
            for (int i = 0; i <= T; i++) for (int j = 1; j <= K; j++) mf.add(1 + i * N, (T + 1) * N + 1, 1, C * i);
            for (int i = 0; i < M; i++) {
                int a = sc.nextInt() - 1, b = sc.nextInt() - 1;
                for (int j = 0; j < T; j++) {
                    int cost = 0;
                    for (int l = 1; l <= K; l++) {
                        mf.add(1 + j * N + a, 1 + (j + 1) * N + b, 1, l * l * D - cost);
                        mf.add(1 + j * N + b, 1 + (j + 1) * N + a, 1, l * l * D - cost);
                        cost = l * l * D;
                    }
                }
            }
            int[] res = mf.minCostFlow(0, (T + 1) * N + 1, K);
            System.err.println(res[0]);
            pw.println(res[1]);
        }
    }

    static long TIME_START, TIME_END;

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(new BufferedOutputStream(System.out));
        Runtime rt = Runtime.getRuntime();
        long memBefore = rt.totalMemory() - rt.freeMemory();
        TIME_START = System.currentTimeMillis();
        new Task().solve(sc, pw);
        TIME_END = System.currentTimeMillis();
        long memAfter = rt.totalMemory() - rt.freeMemory();
        pw.close();
        System.err.println("Memory increased: " + (memAfter - memBefore) / 1000000);
        System.err.println("Time used: " + (TIME_END - TIME_START) + ".");
    }

    static class Scanner {
        StringTokenizer st;
        BufferedReader br;
        Scanner(InputStream s) { br = new BufferedReader(new InputStreamReader(s)); }
        Scanner(FileReader s) throws FileNotFoundException { br = new BufferedReader(s); }
        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) st = new StringTokenizer(br.readLine());
            return st.nextToken();
        }
        int nextInt() throws IOException { return Integer.parseInt(next()); }
        long nextLong() throws IOException { return Long.parseLong(next()); }
        String nextLine() throws IOException { return br.readLine(); }
        double nextDouble() throws IOException { return Double.parseDouble(next()); }
        boolean ready() throws IOException { return br.ready(); }
    }
}
